import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { attribution, inspect } from "../lib/authorship.mjs";
import { main } from "../actions/authorship/run.mjs";

for (const signature of [
  "🤖 Generated with [Claude Code](https://claude.ai/code)",
  "Generated by Codex",
  "**Generated using Codex**",
  "Co-authored-by: Copilot <175728472+Copilot@users.noreply.github.com>",
  "Written with GitHub Copilot",
  "Co-Authored-By: Claude Sonnet 4.5 <noreply@anthropic.com>",
  "Co-authored-by: Codex <codex@openai.com>",
  "Signed-off-by: Cursor Agent <cursoragent@cursor.com>",
]) {
  test("a generated signature is rejected: " + signature.split(":")[0], () => {
    assert.deepEqual(attribution("Explanation.\n\n" + signature), [3]);
  });
}

test("human authors, tool discussions and quoted examples remain valid", () => {
  for (const text of [
    "Co-authored-by: Claude Dupont <claude@example.org>",
    "Co-authored-by: Claude <claude@anthropic.com>",
    "    Generated by Codex",
    "Co-authored-by: Jane Smith <jane@anthropic.com>",
    "Update Codex and Claude Code through dependency automation.",
    "Generated by cargo build.",
    "The tool emitted Generated by Codex as a footer.",
    "> Generated by Codex",
    '"Generated by Codex" is a rejected signature.',
    "```text\nGenerated by Codex\n```",
    "~~~text\nGenerated by Codex\n~~~",
  ]) assert.deepEqual(attribution(text), [], text);
});

function fixture(t) {
  const root = mkdtempSync(join(tmpdir(), "change-authorship-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  function git(...args) {
    const result = spawnSync("git", ["-c", "core.hooksPath=/dev/null", "-c", "commit.gpgsign=false", ...args], {
      cwd: root, encoding: "utf8",
      env: { ...process.env, GIT_CONFIG_GLOBAL: "/dev/null", GIT_CONFIG_NOSYSTEM: "1",
        GIT_AUTHOR_NAME: "Qualification", GIT_AUTHOR_EMAIL: "test@example.invalid",
        GIT_COMMITTER_NAME: "Qualification", GIT_COMMITTER_EMAIL: "test@example.invalid" },
    });
    assert.equal(result.status, 0, result.stderr);
    return result.stdout.trim();
  }
  git("init", "--quiet", "--initial-branch=dev");
  git("commit", "--quiet", "--allow-empty", "-m", "chore: initial history\n\nGenerated by Codex");
  const base = git("rev-parse", "HEAD");
  return { root, git, base };
}

test("the actual range excludes old history and includes machine attribution in merge commits", (t) => {
  const f = fixture(t);
  f.git("checkout", "--quiet", "-b", "feature");
  f.git("commit", "--quiet", "--allow-empty", "-m", "fix: preserve human collaboration\n\nCo-authored-by: Claude Dupont <claude@example.org>");
  f.git("checkout", "--quiet", "dev");
  f.git("merge", "--quiet", "--no-ff", "feature", "-m", "Merge feature\n\nGenerated by Codex");
  const head = f.git("rev-parse", "HEAD");
  assert.deepEqual(inspect(f.root, { base: f.base, head, request: { title: "Update tools", body: null } }),
    [{ where: "commit " + head, line: 3 }]);
});

test("a clean actual range passes while request title/body are checked for bots too", (t) => {
  const f = fixture(t);
  f.git("commit", "--quiet", "--allow-empty", "-m", "fix: keep verified outputs");
  const head = f.git("rev-parse", "HEAD");
  assert.deepEqual(inspect(f.root, { base: f.base, head, request: { title: "Update tools", body: "" } }), []);
  assert.deepEqual(inspect(f.root, { base: f.base, head, request: {
    title: "Generated by Codex", body: "Co-authored-by: Codex <codex@openai.com>",
    user: { type: "Bot", login: "renovate[bot]" },
  } }), [{ where: "title", line: 1 }, { where: "description", line: 1 }]);
});

test("malformed or unavailable revisions fail without shell execution", (t) => {
  const f = fixture(t);
  for (const head of ["--all", "HEAD", "a".repeat(40)]) {
    assert.throws(() => inspect(f.root, { base: f.base, head, request: {} }));
  }
});

test("the action reads the event as data and succeeds on a real clean checkout", (t) => {
  const f = fixture(t);
  const event = join(f.root, "event.json");
  writeFileSync(event, JSON.stringify({ pull_request: { title: "Keep outputs", body: null } }));
  main({ GITHUB_EVENT_PATH: event, GITHUB_WORKSPACE: f.root, INPUT_BASE: f.base, INPUT_HEAD: f.base });
  assert.equal(readFileSync(event, "utf8").includes("Keep outputs"), true);
});

test("the shared merge stop includes authorship in the project failure layer", () => {
  const workflow = readFileSync(new URL("../.github/workflows/merge-stops.yml", import.meta.url), "utf8");
  assert.match(workflow, /id: authorship\n\s+uses: \$\/actions\/authorship/);
  assert.match(workflow, /steps\.authorship\.outcome == 'failure'/);
});
